INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_029_M2', 'Compute Infrastructure', '2', 'Examines the concepts and methods required to understand and work with compute infrastructure. The module addresses server architectures, processors, memory, storage controllers, accelerators, and hardware lifecycle, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M2', 'Active'), ('MOD_COURSE_029_M3', 'Storage and Data Infrastructure', '3', 'Examines the concepts and methods required to understand and work with storage and data infrastructure. The module addresses RAID, SAN, NAS, object storage, backup, and data protection, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M3', 'Active'), ('MOD_COURSE_029_M4', 'Data Center Networking', '4', 'Examines the concepts and methods required to understand and work with data center networking. The module addresses topologies, switching, routing, load balancing, network virtualization, and high-availability design, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M4', 'Active'), ('MOD_COURSE_029_M5', 'Power Systems and Energy Management', '5', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance power systems and energy management. The module addresses UPS, generators, power distribution, PUE, demand management, and power quality, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M5', 'Active'), ('MOD_COURSE_029_M6', 'Cooling and Thermal Management', '6', 'Examines the concepts and methods required to understand and work with cooling and thermal management. The module addresses CRAC/CRAH, chilled water, airflow management, heat rejection, and thermal monitoring, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M6', 'Active'), ('MOD_COURSE_029_M7', 'Virtualization and Infrastructure Management', '7', 'Examines the concepts and methods required to understand and work with virtualization and infrastructure management. The module addresses hypervisors, containers, resource pools, capacity management, and infrastructure automation, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M7', 'Active'), ('MOD_COURSE_029_M8', 'Monitoring, Reliability and Emerging Technologies', '8', 'Examines the concepts and methods required to understand and work with monitoring, reliability and emerging technologies. The module addresses DCIM, telemetry, incident management, redundancy, liquid cooling, and edge computing, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M8', 'Active'), ('MOD_COURSE_030_M1', 'Cement and Supplementary Materials', '1', 'Examines the constituent materials or components, their properties, and their influence on system performance cement and supplementary materials. The module addresses cement chemistry, hydration, supplementary cementitious materials, and blended cements, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M1', 'Active'), ('MOD_COURSE_030_M2', 'Aggregates and Mix Constituents', '2', 'Examines the concepts and methods required to understand and work with aggregates and mix constituents. The module addresses aggregate grading, shape and texture, moisture, admixtures, and mixing water, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M2', 'Active'), ('MOD_COURSE_030_M3', 'Concrete Mix Design', '3', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution concrete mix design. The module addresses water-cement ratio, absolute volume method, target strength, workability, and proportioning, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M3', 'Active'), ('MOD_COURSE_030_M4', 'Fresh Concrete', '4', 'Examines the concepts and methods required to understand and work with fresh concrete. The module addresses workability, segregation, bleeding, setting, placing, and compaction, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M4', 'Active'), ('MOD_COURSE_030_M5', 'Hardened Concrete', '5', 'Examines the concepts and methods required to understand and work with hardened concrete. The module addresses strength, modulus, shrinkage, creep, permeability, and microstructure, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M5', 'Active'), ('MOD_COURSE_030_M6', 'Concrete Production and Quality Control', '6', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour concrete production and quality control. The module addresses batching, mixing, transport, sampling, and statistical quality control, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M6', 'Active'), ('MOD_COURSE_030_M7', 'Durability and Special Concretes', '7', 'Examines the concepts and methods required to understand and work with durability and special concretes. The module addresses freeze-thaw, chloride ingress, sulfate attack, alkali-silica reaction, and high-performance and fiber-reinforced concrete, with emphasis on their relationships, assumptions, analytical use, and application within Concrete Technology.', 'MSD_COURSE_030_M7', 'Active'), ('MOD_COURSE_031_M1', 'Site Investigation and Subsurface Characterization', '1', 'Examines the concepts and methods required to understand and work with site investigation and subsurface characterization. The module addresses borings, sampling, in-situ testing, groundwater, and stratigraphy, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M1', 'Active'), ('MOD_COURSE_031_M2', 'Soil Parameters for Foundation Design', '2', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution soil parameters for foundation design. The module addresses unit weight, shear strength, compressibility, permeability, and stiffness, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M2', 'Active'), ('MOD_COURSE_031_M3', 'Shallow Foundations', '3', 'Establishes the foundational models, terminology, and governing principles shallow foundations. The module addresses isolated footings, strip footings, combined footings, raft foundations, and load transfer, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M3', 'Active'), ('MOD_COURSE_031_M4', 'Bearing Capacity', '4', 'Examines the concepts and methods required to understand and work with bearing capacity. The module addresses Terzaghi theory, Meyerhof methods, Vesic concepts, eccentric loading, and inclined loads, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M4', 'Active'), ('MOD_COURSE_031_M5', 'Settlement Analysis', '5', 'Develops the analytical methods used to formulate, solve, and evaluate problems settlement analysis. The module addresses immediate settlement, consolidation settlement, differential settlement, and time-rate effects, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M5', 'Active'), ('MOD_COURSE_031_M6', 'Deep Foundations', '6', 'Establishes the foundational models, terminology, and governing principles deep foundations. The module addresses piles, pile capacity, group action, negative skin friction, and pile load testing, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M6', 'Active'), ('MOD_COURSE_031_M7', 'Foundation Design and Construction', '7', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution foundation design and construction. The module addresses serviceability, structural checks, ground improvement, and construction monitoring, with emphasis on their relationships, assumptions, analytical use, and application within Foundation Engineering.', 'MSD_COURSE_031_M7', 'Active'), ('MOD_COURSE_032_M1', 'Hydrologic Processes', '1', 'Examines the concepts and methods required to understand and work with hydrologic processes. The module addresses precipitation, infiltration, evaporation, interception, runoff, and watershed processes, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M1', 'Active'), ('MOD_COURSE_032_M2', 'Hydrologic Measurement and Data Analysis', '2', 'Develops the analytical methods used to formulate, solve, and evaluate problems hydrologic measurement and data analysis. The module addresses rain gauges, stream gauging, hydrographs, frequency analysis, and data consistency, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M2', 'Active'), ('MOD_COURSE_032_M3', 'Hydrologic Modelling and Design', '3', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution hydrologic modelling and design. The module addresses unit hydrograph, rainfall-runoff models, flood estimation, and design storms, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M3', 'Active'), ('MOD_COURSE_032_M4', 'Reservoirs and Water Storage', '4', 'Examines the concepts and methods required to understand and work with reservoirs and water storage. The module addresses storage-yield analysis, reservoir routing, sedimentation, and operating rules, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M4', 'Active'), ('MOD_COURSE_032_M5', 'Groundwater Resources', '5', 'Examines the concepts and methods required to understand and work with groundwater resources. The module addresses aquifers, Darcy law, well hydraulics, recharge, and groundwater modelling, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M5', 'Active'), ('MOD_COURSE_032_M6', 'Water Resources Systems', '6', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance water resources systems. The module addresses allocation, demand forecasting, systems analysis, optimization, and conjunctive use, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M6', 'Active'), ('MOD_COURSE_032_M7', 'Flood and Drought Management', '7', 'Examines the concepts and methods required to understand and work with flood and drought management. The module addresses flood routing, floodplain management, drought indices, early warning, and risk analysis, with emphasis on their relationships, assumptions, analytical use, and application within Water Resources Engineering.', 'MSD_COURSE_032_M7', 'Active'), ('MOD_COURSE_033_M1', 'Fluid Properties and Fundamental Flow', '1', 'Establishes the foundational models, terminology, and governing principles fluid properties and fundamental flow. The module addresses pressure, viscosity, hydrostatics, Bernoulli equation, and control volumes, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M1', 'Active'), ('MOD_COURSE_033_M2', 'Pipe Flow', '2', 'Examines the concepts and methods required to understand and work with pipe flow. The module addresses laminar flow, turbulent flow, Darcy-Weisbach, minor losses, and pipe networks, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M2', 'Active'), ('MOD_COURSE_033_M3', 'Open Channel Flow', '3', 'Examines the concepts and methods required to understand and work with open channel flow. The module addresses specific energy, critical flow, uniform flow, gradually varied flow, and hydraulic jumps, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M3', 'Active'), ('MOD_COURSE_033_M4', 'Hydraulic Machines', '4', 'Examines the concepts and methods required to understand and work with hydraulic machines. The module addresses centrifugal pumps, reciprocating pumps, turbines, cavitation, and performance curves, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M4', 'Active'), ('MOD_COURSE_033_M5', 'Hydraulic Structures', '5', 'Examines the concepts and methods required to understand and work with hydraulic structures. The module addresses weirs, spillways, culverts, energy dissipators, and intake structures, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M5', 'Active'), ('MOD_COURSE_033_M6', 'Transient Flow and Water Hammer', '6', 'Examines the concepts and methods required to understand and work with transient flow and water hammer. The module addresses surge pressure, elastic pipe flow, wave speed, and surge control, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M6', 'Active'), ('MOD_COURSE_033_M7', 'Hydraulic System Design', '7', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution hydraulic system design. The module addresses network analysis, pump selection, system curves, and operational control, with emphasis on their relationships, assumptions, analytical use, and application within Hydraulics and Hydraulic Engineering.', 'MSD_COURSE_033_M7', 'Active'), ('MOD_COURSE_034_M1', 'Minerals and Rocks', '1', 'Examines the concepts and methods required to understand and work with minerals and rocks. The module addresses mineral identification, igneous rocks, sedimentary rocks, and metamorphic rocks, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M1', 'Active'), ('MOD_COURSE_034_M2', 'Weathering and Geological Processes', '2', 'Examines the concepts and methods required to understand and work with weathering and geological processes. The module addresses physical weathering, chemical weathering, erosion, and mass wasting, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M2', 'Active'), ('MOD_COURSE_034_M3', 'Geological Structures and Discontinuities', '3', 'Examines the concepts and methods required to understand and work with geological structures and discontinuities. The module addresses bedding, folds, faults, joints, and shear zones, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M3', 'Active'), ('MOD_COURSE_034_M4', 'Engineering Site Characterization', '4', 'Examines the concepts and methods required to understand and work with engineering site characterization. The module addresses geological mapping, discontinuity surveys, rock mass description, and geophysical methods, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M4', 'Active'), ('MOD_COURSE_034_M5', 'Geological Hazards', '5', 'Examines the concepts and methods required to understand and work with geological hazards. The module addresses landslides, earthquakes, subsidence, expansive materials, and erosion hazards, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M5', 'Active'), ('MOD_COURSE_034_M6', 'Geology for Foundations and Excavations', '6', 'Establishes the foundational models, terminology, and governing principles geology for foundations and excavations. The module addresses rock foundations, slope stability inputs, tunnelling geology, and excavation conditions, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M6', 'Active'), ('MOD_COURSE_034_M7', 'Geology in Infrastructure Projects', '7', 'Examines the concepts and methods required to understand and work with geology in infrastructure projects. The module addresses dams, tunnels, roads, groundwater, and geological risk assessment, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Geology.', 'MSD_COURSE_034_M7', 'Active'), ('MOD_COURSE_035_M1', 'Geometric Modelling', '1', 'Examines the concepts and methods required to understand and work with geometric modelling. The module addresses wireframe, surface modelling, solid modelling, parametric features, and constraints, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M1', 'Active'), ('MOD_COURSE_035_M2', 'Computer-Aided Design', '2', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution computer-aided design. The module addresses sketching, assemblies, design intent, tolerancing, and design documentation, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M2', 'Active'), ('MOD_COURSE_035_M3', 'Engineering Graphics and Product Definition', '3', 'Examines the concepts and methods required to understand and work with engineering graphics and product definition. The module addresses sectioning, dimensioning, geometric dimensioning and tolerancing, and bills of materials, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M3', 'Active'), ('MOD_COURSE_035_M4', 'Manufacturing Planning', '4', 'Examines the concepts and methods required to understand and work with manufacturing planning. The module addresses process planning, routing, tooling, setup planning, and computer-aided process planning, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M4', 'Active'), ('MOD_COURSE_035_M5', 'CNC Programming and Machining', '5', 'Examines the concepts and methods required to understand and work with cnc programming and machining. The module addresses coordinate systems, G-code, tool paths, interpolation, and machining simulation, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M5', 'Active'), ('MOD_COURSE_035_M6', 'Computer-Aided Manufacturing', '6', 'Examines the concepts and methods required to understand and work with computer-aided manufacturing. The module addresses CAM workflows, tool-path generation, verification, post-processing, and machining optimization, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M6', 'Active'), ('MOD_COURSE_035_M7', 'CAD/CAM Integration and Product Data', '7', 'Examines the concepts and methods required to understand and work with cad/cam integration and product data. The module addresses associativity, product data exchange, PLM, digital thread, and model-based definition, with emphasis on their relationships, assumptions, analytical use, and application within CAD/CAM.', 'MSD_COURSE_035_M7', 'Active'), ('MOD_COURSE_036_M1', 'Sensors and Transducers', '1', 'Examines the concepts and methods required to understand and work with sensors and transducers. The module addresses measurement principles, position, velocity, force, pressure, and temperature sensing, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M1', 'Active') ON CONFLICT DO NOTHING;